sp_widget.script:
(function() { data.stats = { total: 0, active: 0, draft: 0, archived: 0 };
  try { var gr = new GlideRecord("x_1433041_identi_0_template"); gr.setLimit(200); gr.query();
    while (gr.next()) { data.stats.total++; var s = gr.getValue("status"); if (s === "active") data.stats.active++; else if (s === "draft") data.stats.draft++; else data.stats.archived++; }
  } catch (e) { gs.error("IBAR Template Stats widget error: " + e.message); }
})();
